  const {data:rels,error}=await a.service.from("friendships")
    .select("id,requester_id,addressee_id,status,created_at")
    .or("requester_id.eq."+a.user.id+",addressee_id.eq."+a.user.id)
    .order("created_at",{ascending:false});
