import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@supabase/supabase-js";
import { getSupabaseServiceClient } from "@/lib/server-supabase";

type PortfolioItem={id:string;title:string;video_url:string;display_url?:string;tags:string[];ai_score:number|null};

export default async function PublicPortfolio({params}:{params:Promise<{username:string}>}) {
  const {username}=await params;
  const url=process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key=process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;

  let profile:any=null;
  let items:PortfolioItem[]=[];

  if(url&&key){
    const supabase=createClient(url,key,{auth:{persistSession:false}});
    const {data}=await supabase.from("public_profiles")
      .select("id,display_name,username,level,ai_score,skills")
      .eq("username",username).maybeSingle();
    profile=data;
    if(profile){
      const {data:portfolio}=await supabase.from("portfolio_items")
        .select("id,title,video_url,tags,ai_score")
        .eq("editor_id",profile.id)
        .order("created_at",{ascending:false});
      items=(portfolio||[]) as PortfolioItem[];
      const service=getSupabaseServiceClient();
      if(service){
        items=await Promise.all(items.map(async item=>{
          if(/^https?:\/\//.test(item.video_url))return {...item,display_url:item.video_url};
          const {data:signed}=await service.storage.from("challenge-submissions").createSignedUrl(item.video_url,60*15);
          return {...item,display_url:signed?.signedUrl||""};
        }));
      }else{
        items=items.map(item=>({...item,display_url:/^https?:\/\//.test(item.video_url)?item.video_url:""}));
      }
    }
  }

  if(!profile&&username==="demo"){
    profile={display_name:"EDITA Demo Editor",username:"demo",level:5,ai_score:82,skills:["Short-form","CapCut","Talking Head"]};
    items=[
      {id:"1",title:"VOLT / Gym Promo",video_url:"",tags:["ads","reels"],ai_score:91},
      {id:"2",title:"Finance Expert Reel",video_url:"",tags:["talking-head"],ai_score:86},
      {id:"3",title:"North Coffee Challenge",video_url:"",tags:["winner","commercial"],ai_score:90},
    ];
  }

  if(!profile) notFound();

  return <main className="public-portfolio">
    <div className="portfolio-shell">
      <nav className="pricing-nav"><Link href="/" className="brand">EDITA<span>.</span></Link><Link href="/signup">Создать свой профиль</Link></nav>
      <div className="portfolio-hero">
        <div><div className="eyebrow">VERIFIED EDITOR</div><h1>{profile.display_name}</h1><p>@{profile.username}</p></div>
        <div className="portfolio-score"><strong>{profile.ai_score||"—"}</strong><span>AI Skill Score</span></div>
      </div>
      <div className="portfolio-tags">{(profile.skills||[]).map((s:string)=><span className="tag" key={s}>{s}</span>)}</div>
      <section className="portfolio-work-grid">
        {items.length?items.map(item=><article className="portfolio-work" key={item.id}>
          <div className="work-preview">{item.display_url&&isDirectVideo(item.display_url)?<video controls preload="metadata" src={item.display_url}/>:<span>EDITA WORK</span>}</div>
          <h2>{item.title}</h2>
          <div className="work-meta"><span>{(item.tags||[]).join(" · ")}</span>{item.ai_score!=null&&<b>AI {item.ai_score}</b>}</div>{item.display_url&&!isDirectVideo(item.display_url)&&<a className="work-link" href={item.display_url} target="_blank" rel="noreferrer">Открыть работу ↗</a>}
        </article>):<div className="legal-card"><p>Портфолио пока пустое.</p></div>}
      </section>
    </div>
  </main>
}

function isDirectVideo(url:string){return /\\.(mp4|webm|mov)(\\?|$)/i.test(url)||url.includes("supabase")}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type BrandContext={
  audience:string;
  tone:string;
  colors:string;
  references:string;
  editingRules:string;
};

const empty:BrandContext={audience:"",tone:"",colors:"",references:"",editingRules:""};

export default function BrandBrain({viewerName="Business"}:{viewerName?:string}){
  const [form,setForm]=useState<BrandContext>(empty);
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [message,setMessage]=useState("");

  useEffect(()=>{void load()},[]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){
      try{
        const raw=localStorage.getItem("edita_brand_brain");
        if(raw)setForm(JSON.parse(raw));
      }catch{}
      return;
    }
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)return;
    let {data}=await supabase.from("businesses").select("id,brand_context").eq("owner_id",user.id).maybeSingle();
    if(!data){
      const {data:created}=await supabase.from("businesses")
        .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
        .select("id,brand_context")
        .single();
      data=created;
    }
    if(data){
      setBusinessId(data.id);
      setForm({...empty,...(data.brand_context||{})});
    }
  }

  async function save(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase||!businessId){
      localStorage.setItem("edita_brand_brain",JSON.stringify(form));
      setMessage("Профиль бренда сохранён локально в demo.");
      return;
    }
    const {error}=await supabase.from("businesses").update({brand_context:form}).eq("id",businessId);
    setMessage(error?error.message:"Профиль бренда сохранён. Его можно использовать для новых ТЗ и AI-проверок.");
  }

  return <section className="card brand-brain">
    <div className="eyebrow">ПРОФИЛЬ БРЕНДА</div>
    <h3>Контекст бренда для всех монтажёров</h3>
    <p className="muted">Сохраняем стиль один раз, чтобы новый редактор не начинал с нуля.</p>
    <form className="business-form" onSubmit={save}>
      <input placeholder="Целевая аудитория" value={form.audience} onChange={e=>setForm({...form,audience:e.target.value})}/>
      <input placeholder="Tone of voice: премиальный, дерзкий, спокойный…" value={form.tone} onChange={e=>setForm({...form,tone:e.target.value})}/>
      <input placeholder="Цвета / шрифты / визуальные правила" value={form.colors} onChange={e=>setForm({...form,colors:e.target.value})}/>
      <input placeholder="Ссылки на лучшие референсы" value={form.references} onChange={e=>setForm({...form,references:e.target.value})}/>
      <textarea placeholder="Повторяющиеся пожелания по монтажу и правкам" value={form.editingRules} onChange={e=>setForm({...form,editingRules:e.target.value})}/>
      <button className="btn btn-dark">Сохранить Профиль бренда</button>
    </form>
    {message&&<div className="auth-msg">{message}</div>}
  </section>
}

"use client";

import {FormEvent,useEffect,useState} from "react";
