    {rows.map((row,i)=><article className="leader-row" key={row.id}>
      <div className="leader-rank">#{i+1}</div>
      <div className="leader-main"><b>{row.display_name||"Editor"}</b><span>{(row.skills||[]).slice(0,3).join(" · ")||"Video editing"}</span></div>
      <div className="leader-stat"><strong>{row.ai_score??"—"}</strong><span>AI Score</span></div>
      <div className="leader-stat"><strong>{row.level}</strong><span>Level</span></div>
      {row.username?<Link className="btn btn-ghost" href={"/u/"+row.username}>Профиль</Link>:<span/>}
    </article>)}
    <p className="muted">В рейтинг не выводятся email, возрастная группа, платежи, доход и приватный onboarding.</p>
  </div>
}

"use client";

import Link from "next/link";
import {useEffect,useState} from "react";

export default function CookieNotice(){
  const [show,setShow]=useState(false);
  useEffect(()=>{
    try{if(!localStorage.getItem("edita_cookie_notice_v1"))setShow(true)}catch{}
  },[]);
  if(!show)return null;
  function close(){
    try{localStorage.setItem("edita_cookie_notice_v1","seen")}catch{}
    setShow(false);
  }
  return <div className="cookie-notice" role="dialog" aria-label="Информация о cookie">
    <div>
      <b>Файлы cookie</b>
      <span>Сейчас EDITA использует только технические cookie: для входа, безопасности, оплаты и доступа к закрытому предзапуску. Рекламные cookie не включены.</span>
    </div>
    <div className="cookie-actions"><Link href="/cookies">Подробнее</Link><button className="btn btn-dark" onClick={close}>Понятно</button></div>
  </div>
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type State={
  emailVerified:boolean;
  ageGroup:string;
  guardianVerified:boolean;
  level:string;
  request?:{status:string;review_note?:string|null}|null;
};

export default function EditorVerification(){
  const [state,setState]=useState<State|null>(null);
  const [form,setForm]=useState({portfolioUrl:"",sampleUrl:"",note:""});
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    const h=await headers();
    const r=await fetch("/api/editor/verification",{headers:h,cache:"no-store"});
    const data=await r.json();
    if(r.ok)setState(data);
  }

  useEffect(()=>{void load()},[]);

  async function submit(e:FormEvent){
    e.preventDefault();setLoading(true);setMessage("");
    const h=await headers();
    const r=await fetch("/api/editor/verification",{
      method:"POST",
      headers:{...h,"Content-Type":"application/json"},
      body:JSON.stringify(form)
    });
    const data=await r.json();
    setLoading(false);
    if(!r.ok){setMessage(data?.error||"Не удалось отправить.");return;}
    setMessage("Работа отправлена на проверку. Мы смотрим именно навык монтажа — паспорт для этого не нужен.");
    await load();
  }

  if(!state)return null;
  const minor=state.ageGroup!=="18+";

  return <section className="card">
    <div className="eyebrow">ПРОВЕРКА МОНТАЖЁРА</div>
    <h3>Не такая, как у бизнеса</h3>
    <p className="muted">Компания подтверждает документы. Монтажёр подтверждает email, возрастной доступ и свой навык работой или портфолио.</p>

    <div className="verification-checks">
      <div className={state.emailVerified?"check-ok":"check-wait"}><b>{state.emailVerified?"✓":"○"} Email</b><span>{state.emailVerified?"Подтверждён":"Нужно подтвердить письмо"}</span></div>
      <div className={!minor||state.guardianVerified?"check-ok":"check-wait"}><b>{!minor||state.guardianVerified?"✓":"○"} Возрастной доступ</b><span>{!minor?"18+ указано при регистрации":state.guardianVerified?"Родитель подтверждён":"Ждём подтверждение родителя"}</span></div>
      <div className={state.level==="skills_verified"?"check-ok":"check-wait"}><b>{state.level==="skills_verified"?"✓":"○"} Навык монтажа</b><span>{state.level==="skills_verified"?"Работа проверена EDITA":state.request?.status==="pending"?"Работа на проверке":"Можно отправить портфолио или одну работу"}</span></div>
    </div>

    {state.level!=="skills_verified"&&state.request?.status!=="pending"&&<form className="business-form" onSubmit={submit}>
      <input type="url" placeholder="Ссылка на портфолио" value={form.portfolioUrl} onChange={e=>setForm({...form,portfolioUrl:e.target.value})}/>
      <input type="url" placeholder="Или ссылка на одну работу" value={form.sampleUrl} onChange={e=>setForm({...form,sampleUrl:e.target.value})}/>
      <textarea placeholder="Что ты делал в этой работе? Например: нарезка, субтитры, звук." value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/>
      <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем…":"Отправить навык на проверку"}</button>
    </form>}

    {state.request?.status==="rejected"&&<div className="auth-msg">Нужно исправить: {state.request.review_note||"добавь более понятную работу и отправь новую заявку."}</div>}
    {message&&<div className="auth-msg">{message}</div>}
  </section>
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Data={
  needed:boolean;
  verified:boolean;
  request?:{status:string;review_note?:string|null;guardian_email?:string|null}|null;
};

export default function GuardianVerification(){
  const [data,setData]=useState<Data|null>(null);
  const [form,setForm]=useState({guardianName:"",guardianEmail:"",relationship:"Родитель"});
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    const h=await headers();
    const r=await fetch("/api/guardian/verification",{headers:h,cache:"no-store"});
    const json=await r.json();
    if(r.ok)setData(json);
  }

  useEffect(()=>{void load()},[]);

  async function submit(e:FormEvent){
    e.preventDefault();setLoading(true);setMessage("");
    try{
      const h=await headers();
      const r=await fetch("/api/guardian/verification",{
        method:"POST",
        headers:{...h,"Content-Type":"application/json"},
        body:JSON.stringify(form)
      });
      const json=await r.json();
      if(!r.ok)throw new Error(json?.error||"Не удалось отправить заявку.");
      setMessage("Заявка отправлена. До подтверждения можно учиться, но коммерческие функции останутся закрыты.");
      await load();
    }catch(e){
      setMessage(e instanceof Error?e.message:"Ошибка.");
    }finally{setLoading(false)}
  }

  if(!data?.needed)return null;
  if(data.verified)return <section className="card"><div className="eyebrow">БЕЗОПАСНОСТЬ</div><h3>Родитель подтверждён ✓</h3><p className="muted">Коммерческие функции доступны с учётом остальных правил EDITA.</p></section>;

  if(data.request?.status==="pending")return <section className="card"><div className="eyebrow">БЕЗОПАСНОСТЬ</div><h3>Ждём подтверждение родителя</h3><p className="muted">Заявка уже отправлена. Учиться и пользоваться AI можно. Вакансии, оплата и коммерческие Challenge пока закрыты.</p></section>;

  return <section className="card">
    <div className="eyebrow">БЕЗОПАСНОСТЬ ДЛЯ ПОЛЬЗОВАТЕЛЕЙ ДО 18 ЛЕТ</div>
    <h3>Подтверждение родителя</h3>
    <p className="muted">Мы не просим загружать паспорт ребёнка в обычную форму. Для закрытого предзапуска заявка проверяется вручную. Для публичного запуска EDITA должна использовать отдельный сервис проверки личности родителя и хранить только результат проверки.</p>
    <form className="business-form" onSubmit={submit}>
      <input required placeholder="Имя и фамилия родителя" value={form.guardianName} onChange={e=>setForm({...form,guardianName:e.target.value})}/>
      <input required type="email" placeholder="Email родителя" value={form.guardianEmail} onChange={e=>setForm({...form,guardianEmail:e.target.value})}/>
      <select value={form.relationship} onChange={e=>setForm({...form,relationship:e.target.value})}>
        <option>Родитель</option>
        <option>Опекун</option>
        <option>Попечитель</option>
        <option>Другой законный представитель</option>
      </select>
      <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем…":"Отправить заявку"}</button>
    </form>
    {message&&<div className="auth-msg">{message}</div>}
  </section>
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Job={id:string;title:string;description:string;budget_min_cents:number|null;budget_max_cents:number|null;businesses?:{name?:string;verified?:boolean;verification_level?:string}|null};
const demoJobs:Job[]=[
  {id:"d1",title:"Reels-монтажёр",description:"5–7 short-form роликов в неделю.",budget_min_cents:4500000,budget_max_cents:6000000,businesses:{name:"Demo Brand"}},
  {id:"d2",title:"YouTube Shorts",description:"Экспертный talking-head + B-roll.",budget_min_cents:250000,budget_max_cents:350000,businesses:{name:"Creator Studio"}},
  {id:"d3",title:"UGC ads editor",description:"Коммерческие performance-креативы.",budget_min_cents:6000000,budget_max_cents:8000000,businesses:{name:"Growth Team"}},
];

export default function JobBoard({mode,viewerName="Business",ageGroup,guardianVerified}:{mode:"editor"|"business";viewerName?:string;ageGroup?:string;guardianVerified?:boolean}){
  const [jobs,setJobs]=useState<Job[]>([]);
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [businessVerified,setBusinessVerified]=useState(false);
  const [message,setMessage]=useState("");
  const [form,setForm]=useState({title:"",description:"",min:"",max:""});

  useEffect(()=>{void load()},[mode]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setJobs(demoJobs);return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setJobs(demoJobs);return;}

    if(mode==="business"){
      let {data:business}=await supabase.from("businesses").select("id,verified,verification_level").eq("owner_id",user.id).maybeSingle();
      if(!business){
        const {data:created}=await supabase.from("businesses")
          .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
          .select("id,verified,verification_level")
          .single();
        business=created;
      }
      if(!business){setJobs([]);setMessage("Не удалось создать Business Workspace.");return;}
      setBusinessId(business.id);
      setBusinessVerified(Boolean((business as any).verified));
      const {data,error}=await supabase.from("jobs").select("id,title,description,budget_min_cents,budget_max_cents").eq("business_id",business.id).order("created_at",{ascending:false});
      if(error){setMessage(error.message);return;}
      setJobs((data||[]) as Job[]);
    }else{
      const {data,error}=await supabase.from("jobs").select("id,business_id,title,description,budget_min_cents,budget_max_cents").eq("status","open").order("created_at",{ascending:false});
      if(error){setMessage(error.message);setJobs(demoJobs);return;}
      const rows=(data||[]) as any[];
      const businessIds=[...new Set(rows.map(j=>j.business_id).filter(Boolean))];
      const {data:brands}=businessIds.length?await supabase.from("public_businesses").select("id,name,verified,verification_level").in("id",businessIds):{data:[] as any[]};
      const brandMap=Object.fromEntries((brands||[]).map((b:any)=>[b.id,b]));
      setJobs(rows.map(j=>({...j,businesses:{
        name:brandMap[j.business_id]?.name||"Business",
        verified:Boolean(brandMap[j.business_id]?.verified),
        verification_level:brandMap[j.business_id]?.verification_level||"basic"
      }})) as Job[]);
    }
  }

  async function apply(jobId:string){
    if(mode==="editor"&&ageGroup&&ageGroup!=="18+"&&!guardianVerified){setMessage("Сначала нужно подтверждение родителя или законного представителя. Учиться можно без него.");return;}
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setMessage("Пример: заявка сохранена только в браузере.");return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди, чтобы податься.");return;}
    const {error}=await supabase.from("job_applications").upsert({job_id:jobId,editor_id:user.id,status:"applied"},{onConflict:"job_id,editor_id"});
    setMessage(error?error.message:"Заявка отправлена бизнесу.");
  }

  async function create(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase||!businessId){setMessage("Без аккаунта вакансия не публикуется.");return;}
    if(!businessVerified){setMessage("Сначала пройди проверку компании. После этого можно публиковать реальные вакансии.");return;}
    const {error}=await supabase.from("jobs").insert({
      business_id:businessId,title:form.title,description:form.description,status:"open",
      budget_min_cents:form.min?Math.round(Number(form.min)*100):null,
      budget_max_cents:form.max?Math.round(Number(form.max)*100):null
    });
    if(error){setMessage(error.message);return;}
    setForm({title:"",description:"",min:"",max:""});setMessage("Вакансия опубликована.");
    await load();
  }

  return <div className="job-board">
    {mode==="business"&&<section className="card"><div className="eyebrow">НОВАЯ ВАКАНСИЯ</div><h3>Опубликовать вакансию</h3>{!businessVerified&&<div className="auth-msg">Сначала нужна проверка компании. Это защищает монтажёров от фейковых работодателей.</div>}<form className="business-form" onSubmit={create}>
      <input required placeholder="Название роли" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
      <textarea required placeholder="Задачи, объём, формат работы" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/>
      <div className="split-fields"><input type="number" min="0" placeholder="От, ₽" value={form.min} onChange={e=>setForm({...form,min:e.target.value})}/><input type="number" min="0" placeholder="До, ₽" value={form.max} onChange={e=>setForm({...form,max:e.target.value})}/></div>
      <button className="btn btn-dark" disabled={!businessVerified}>{businessVerified?"Опубликовать":"Сначала пройти проверку"}</button>
    </form></section>}

    <section className="grid job-grid">{jobs.map(job=><article className="card job" key={job.id}>
      <small>{mode==="editor"?(job.businesses?.name||"Business"):"ВАША ВАКАНСИЯ"}</small>
      {mode==="editor"&&job.businesses?.verified&&<span className="tag verification-mini">{badgeName(job.businesses.verification_level)}</span>}
      <h3>{job.title}</h3><p className="muted">{job.description}</p>
      <b>{budget(job)}</b>
      {mode==="editor"&&<button className="btn btn-dark" onClick={()=>apply(job.id)}>Податься</button>}
    </article>)}</section>
    {message&&<div className="auth-msg">{message}</div>}
  </div>
}

function budget(job:Job){
  const min=job.budget_min_cents?Math.round(job.budget_min_cents/100):null;
  const max=job.budget_max_cents?Math.round(job.budget_max_cents/100):null;
  if(min&&max)return new Intl.NumberFormat("ru-RU").format(min)+"–"+new Intl.NumberFormat("ru-RU").format(max)+" ₽";
  if(min)return "от "+new Intl.NumberFormat("ru-RU").format(min)+" ₽";
  if(max)return "до "+new Intl.NumberFormat("ru-RU").format(max)+" ₽";
  return "Бюджет по договорённости";
}


function badgeName(level?:string){
  if(level==="popular_brand")return "★ Известный бренд";
  if(level==="partner")return "★ Партнёр EDITA";
  return "✓ Проверенная компания";
}

"use client";

import { useState } from "react";
import { getSupabaseBrowserClient } from "@/lib/supabase-browser";

export default function PayButton({product,label}:{product:"start"|"ai-pro-30";label:string}) {
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState("");

  async function pay(){
    setLoading(true);setError("");
    try{
      const supabase=getSupabaseBrowserClient();
      const session=supabase?(await supabase.auth.getSession()).data.session:null;
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;

      const r=await fetch("/api/payments/yookassa/create",{
        method:"POST",
        headers,
        body:JSON.stringify({product})
      });
      const data=await r.json();
      if(r.status===401){window.location.href="/login";return;}
      if(!r.ok||!data.confirmationUrl)throw new Error(data?.error||"Не удалось создать платёж");
      window.location.href=data.confirmationUrl;
    }catch(e){
      setError(e instanceof Error?e.message:"Ошибка оплаты");
      setLoading(false);
    }
  }

  return <div className="pay-action">
    <button className="btn btn-dark" onClick={pay} disabled={loading}>{loading?"Переходим к оплате…":label}</button>
    {error&&<div className="auth-msg">{error}</div>}
  </div>
}

"use client";
import {useEffect,useMemo,useState} from "react";
import Link from "next/link";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
